  "schema_version": 1,
  "verdict": "needs-correction",
  "finding_class": "metadata-only",
  "rationale": "Obesitas and obesiti are valid Indonesian and Malaysian Malay health terms, respectively, but the national split is materially overstated as an exclusive distinction: kegemukan is an ordinary accepted equivalent in both varieties. The relation should be framed as a national preference or conventional technical-form contrast, not a strict vocabulary boundary. The English cue and sense are accurate. The two answers are semantically correct. There is no false-friend contrast: the forms are transparent cognates with the same meaning.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "Correct: obesity refers to abnormal or excessive body-fat accumulation that can impair or risk health.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.who.int/health-topics/obesity"
      ]
    },
    {
      "subject": "Indonesian answer: obesitas",
      "conclusion": "Correct and ordinary in Indonesian health usage; Indonesian Ministry of Health material defines obesitas as excessive accumulation of body fat.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.kemkes.go.id/id/dianggap-bukan-penyakit-obesitas-justru-ancam-picu-komplikasi",
        "https://keslan.kemkes.go.id/view_artikel/3617/mengenal-obesitas"
      ]
    },
    {
      "subject": "Malaysian answer: obesiti",
      "conclusion": "Correct and established in Malaysian Malay; DBP lists obesiti as excess-fat-related kegemukan and states that the term is accepted by users.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=obesiti"
      ]
    },
    {
      "subject": "Cross-variety overlap and national split",
      "conclusion": "Material overlap exists. Indonesian health material explicitly pairs kegemukan with obesitas, while Malaysian DBP defines obesiti through kegemukan; Malaysian health material also uses kegemukan alongside obesity terminology. The current different-common-word relation therefore overstates national separation unless presented as a preferred technical form rather than an exclusive equivalent.",
      "material_risk": true,
      "evidence_refs": [
        "https://p2ptm.kemkes.go.id/uploads/VHcrbkVobjRzUDN3UCs4eUJ0dVBndz09/2019/03/Buku_Pintar_Kader_POSBINDU.pdf",
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=obesiti",
        "https://www.moh.gov.my/images/04-penerbitan/rujukan/penyakit-berjangkit/kospen/MODUL%20LATIHAN_KOSPEN.pdf"
      ]
    },
    {
      "subject": "Final relation",
      "conclusion": "Needs qualification or metadata correction. Different-common-word is defensible only as a preferred/conventional national-form contrast; it is misleading if it implies that obesitas is not accepted in Malaysian Malay, obesiti is not accepted in Indonesian, or kegemukan is not ordinary in both.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=obesiti",
        "https://p2ptm.kemkes.go.id/uploads/VHcrbkVobjRzUDN3UCs4eUJ0dVBndz09/2019/03/Buku_Pintar_Kader_POSBINDU.pdf"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "No false-friend contrast is warranted. Obesitas and obesiti are spelling variants with the same medical sense, not deceptive cross-variety forms. The empty contrast field is acceptable, though the card could explicitly mark the forms as cognate equivalents.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.who.int/health-topics/obesity",
        "https://prpm.dbp.gov.my/Cari1?d=243192&keyword=obesiti"
      ]
    }
  ]
}
